import { useQuery } from '@tanstack/react-query'
import { api } from '@/lib/api'
import { Database, Search } from 'lucide-react'
import { useState } from 'react'

export function Memory() {
  const { data: memory } = useQuery({ queryKey: ['memory'], queryFn: api.getMemory })
  const [query, setQuery] = useState('')
  const [searchResults, setSearchResults] = useState<unknown[]>([])
  const [searching, setSearching] = useState(false)

  const handleSearch = async () => {
    if (!query.trim()) return
    setSearching(true)
    try {
      const res = await api.searchMemory(query.trim())
      setSearchResults(res.records || [])
    } catch { /* ignore */ }
    finally { setSearching(false) }
  }

  return (
    <div className="p-6 space-y-6">
      <div>
        <h2 className="text-2xl font-bold">记忆管理</h2>
        <p className="text-muted-foreground">短期记忆、长期记忆与意图缓存</p>
      </div>

      {/* Stats */}
      {memory && (
        <div className="grid gap-4 sm:grid-cols-3">
          <div className="rounded-xl border bg-card p-4">
            <p className="text-xs text-muted-foreground">短期记忆</p>
            <p className="text-2xl font-bold">{memory.stats.short_term}</p>
          </div>
          <div className="rounded-xl border bg-card p-4">
            <p className="text-xs text-muted-foreground">归档记忆</p>
            <p className="text-2xl font-bold">{memory.stats.archived}</p>
          </div>
          <div className="rounded-xl border bg-card p-4">
            <p className="text-xs text-muted-foreground">存储后端</p>
            <p className="text-2xl font-bold capitalize">{memory.stats.backend}</p>
          </div>
        </div>
      )}

      {/* Search */}
      <div className="rounded-xl border bg-card p-4">
        <h3 className="font-medium mb-3 flex items-center gap-2">
          <Search className="h-4 w-4" /> 记忆搜索
        </h3>
        <div className="flex gap-2">
          <input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="搜索关键词..."
            className="flex-1 rounded-lg border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
            onKeyDown={(e) => { if (e.key === 'Enter') handleSearch() }}
          />
          <button
            onClick={handleSearch}
            disabled={searching}
            className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground hover:bg-primary/90"
          >
            {searching ? '搜索中...' : '搜索'}
          </button>
        </div>
        {searchResults.length > 0 && (
          <div className="mt-3 space-y-2">
            {searchResults.map((r, i) => (
              <pre key={i} className="rounded bg-muted p-3 text-xs overflow-auto">
                {JSON.stringify(r, null, 2)}
              </pre>
            ))}
          </div>
        )}
      </div>

      {/* Recent records */}
      <div className="rounded-xl border bg-card p-4">
        <h3 className="font-medium mb-3 flex items-center gap-2">
          <Database className="h-4 w-4" /> 最近记录
        </h3>
        {!memory || memory.records.length === 0 ? (
          <p className="text-sm text-muted-foreground">暂无记忆记录</p>
        ) : (
          <div className="space-y-2">
            {memory.records.slice(0, 20).map((r, i) => (
              <pre key={i} className="rounded bg-muted p-2 text-xs overflow-auto">
                {JSON.stringify(r, null, 2)}
              </pre>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}
